#include "vocal_model.h"
#include <chrono>
#include <iostream>
#include <thread>
#include <filesystem>
int wmain(int argc,wchar_t**argv){try{if(argc<2)return 2;VocalModel model(argv[1]);std::array<float,256> audio{};std::vector<double> times;double energy=0;const int hops=argc>2?_wtoi(argv[2]):5000;bool paced=argc>3;auto begin=std::chrono::steady_clock::now();for(int h=0;h<hops;h++){for(int c=0;c<2;c++)for(int i=0;i<128;i++)audio[c*128+i]=float(.05*sin((h*128+i)*6.283185307179586*(c?443:701)/44100));auto t=std::chrono::steady_clock::now();auto out=model.process(audio.data());auto end=std::chrono::steady_clock::now();if(h>=100)times.push_back(std::chrono::duration<double,std::micro>(end-t).count());for(int i=0;i<256;i++)energy+=out[i]*out[i];if(paced)std::this_thread::sleep_until(begin+std::chrono::duration_cast<std::chrono::steady_clock::duration>(std::chrono::duration<double>((h+1)*128./44100.)));}std::sort(times.begin(),times.end());double sum=0;size_t late=0;for(auto x:times){sum+=x;if(x>128e6/44100)late++;}std::cout<<"{\"hops\":"<<hops<<",\"paced\":"<<(paced?"true":"false")<<",\"p50Us\":"<<times[times.size()/2]<<",\"p99Us\":"<<times[size_t(times.size()*.99)]<<",\"maxUs\":"<<times.back()<<",\"meanUs\":"<<sum/times.size()<<",\"overHopBudget\":"<<late<<",\"outputEnergy\":"<<energy<<"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
